namespace ghidra.file.formats.omf;

using static ghidra.formats.gfilesystem.fileinfo.FileAttributeType;




using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.app.util.bin.format.omf;
using ghidra.app.util.bin.format.omf.omf;
using ghidra.app.util.bin.format.omf.omf;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.fileinfo;
using ghidra.util.task;

/* @FileSystemInfo(type = "omf", description = "OMF Archive", factory = typeof(OmfArchiveFileSystemFactory)) */
public class OmfArchiveFileSystem : AbstractFileSystem<OmfLibraryRecord.MemberHeader> {

	private ByteProvider provider;

	public OmfArchiveFileSystem(FSRLRoot fsFSRL, ByteProvider provider) : base(fsFSRL, FileSystemService.getInstance())
    {
		this.provider = provider;
	}

	public void mount(TaskMonitor monitor)
    {
		monitor.setMessage("Opening OMF archive...");
		OmfLibraryRecord libraryRec =
			OmfLibraryRecord.parse(new OmfRecordFactory(provider), monitor);
		List<OmfLibraryRecord.MemberHeader> memberHeaders = libraryRec.getMemberHeaders();
		foreach (OmfLibraryRecord.MemberHeader member in memberHeaders) {
			string name = member.name;
			monitor.setMessage(name);
			fsIndex.storeFile(name, fsIndex.getFileCount(), false, member.size, member);
		}
	}

	/* @Override */
	public void close()
    {
		refManager.onClose();
		if (provider != null) {
			provider.close();
			provider = null;
		}
		fsIndex.clear();
	}

	/* @Override */
	public bool isClosed() {
		return provider == null;
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor) {
		OmfLibraryRecord.MemberHeader member = fsIndex.getMetadata(file);
		return (member != null)
				? new ByteProviderWrapper(provider, member.payloadOffset, member.size,
					file.getFSRL())
				: null;
	}

	/* @Override */
	public FileAttributes getFileAttributes(GFile file, TaskMonitor monitor) {
		FileAttributes result = new FileAttributes();

		OmfLibraryRecord.MemberHeader entry = fsIndex.getMetadata(file);
		if (entry != null) {
			result.add(NAME_ATTR, entry.name);
			result.add(SIZE_ATTR, entry.size);
		}
		return result;
	}

}
